const sme = $('Normalize Retrieval Outputs').item.json;
const docs = $input.all();

// ---------- helpers ----------
function norm(value) {
  return String(value || '').toLowerCase().trim();
}

function splitList(value) {
  return String(value || '')
    .split(/[;,]/)
    .map(v => v.trim().toLowerCase())
    .filter(Boolean);
}

function fieldMatches(docValue, smeValue) {
  const d = norm(docValue);
  const s = norm(smeValue);

  if (!d || d === 'any' || d === 'all') return true;
  if (!s) return false;

  const dList = splitList(d);
  const sList = splitList(s);

  return dList.some(x => sList.includes(x));
}

function tagMatches(docTags, smeText) {
  const tags = splitList(docTags);
  const text = norm(smeText);

  if (!tags.length || !text) return 0;

  let count = 0;
  for (const tag of tags) {
    if (text.includes(tag)) count += 1;
  }
  return count;
}

function priorityScore(value) {
  const p = norm(value);
  if (p === 'high') return 3;
  if (p === 'medium') return 2;
  if (p === 'low') return 1;

  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

// ---------- SME context ----------
const smeIndustry = norm(sme.industry);
const smeRegion = norm(sme.target_market_region);
const smeBuyer = norm(sme.target_buyer);
const smeGoal = norm(sme.business_goal);
const smeNotes = norm(sme.notes);
const smeSubindustry = norm(sme.subindustry);
const smeLocation = norm(sme.company_location);

const smeContextText = [
  sme.industry,
  sme.subindustry,
  sme.target_market_region,
  sme.target_buyer,
  sme.business_goal,
  sme.notes
].filter(Boolean).join(' ').toLowerCase();

// ---------- score docs ----------
const scored = docs
  .map(item => {
    const doc = item.json;

    const active = norm(doc.active);
    if (active && active !== 'true') return null;

    let score = 0;
    const reasons = [];

    // priority base
    const pScore = priorityScore(doc.priority);
    score += pScore;
    if (pScore > 0) reasons.push(`priority: ${doc.priority}`);

    // industry
    if (fieldMatches(doc.industry, smeIndustry)) {
      score += 4;
      if (norm(doc.industry) && norm(doc.industry) !== 'any') {
        reasons.push(`industry match: ${doc.industry}`);
      }
    }

    // region
    if (fieldMatches(doc.region, smeRegion) || fieldMatches(doc.region, smeLocation)) {
      score += 3;
      if (norm(doc.region) && norm(doc.region) !== 'any') {
        reasons.push(`region match: ${doc.region}`);
      }
    }

    // buyer type
    if (fieldMatches(doc.buyer_type, smeBuyer)) {
      score += 3;
      if (norm(doc.buyer_type) && norm(doc.buyer_type) !== 'any') {
        reasons.push(`buyer match: ${doc.buyer_type}`);
      }
    }

    // topic tags
    const tagHitCount = tagMatches(doc.topic_tags, smeContextText);
    if (tagHitCount > 0) {
      score += tagHitCount * 2;
      reasons.push(`topic tag hits: ${tagHitCount}`);
    }

    // summary relevance
    const summaryHits = tagMatches(doc.summary, `${smeGoal} ${smeNotes} ${smeSubindustry}`);
    if (summaryHits > 0) {
      score += Math.min(summaryHits, 2);
      reasons.push('summary relevance');
    }

    return {
      json: {
        doc_id: doc.doc_id || '',
        doc_title: doc.doc_title || '',
        doc_type: doc.doc_type || '',
        source: doc.source || '',
        category: doc.category || '',
        industry: doc.industry || '',
        region: doc.region || '',
        buyer_type: doc.buyer_type || '',
        topic_tags: doc.topic_tags || '',
        priority: doc.priority || '',
        active: doc.active || '',
        summary: doc.summary || '',
        link: doc.link || '',
        retrieval_score: score,
        retrieval_reasons: reasons,
        sme_test_id: sme.test_id,
        sme_company_name: sme.company_name
      }
    };
  })
  .filter(Boolean)
  .sort((a, b) => b.json.retrieval_score - a.json.retrieval_score);

return scored.slice(0, 8);

const sme = $('Normalize Retrieval Outputs').first().json;
const docs = $('Select Matching Documents').all();
const chunks = $('Select Matching Chunks').all();

function parseMaybeJson(value, fallback) {
  if (value === null || value === undefined || value === '') return fallback;
  if (Array.isArray(value) || typeof value === 'object') return value;

  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch (e) {
      return fallback;
    }
  }

  return fallback;
}

return [
  {
    json: {
      company_name: sme.company_name || '',
      industry: sme.industry || '',
      subindustry: sme.subindustry || '',
      employee_band: sme.employee_band || '',
      revenue_band: sme.revenue_band || '',
      company_location: sme.company_location || '',
      country: sme.country || '',
      target_market_region: parseMaybeJson(sme.target_market_region, []),
      target_buyer: sme.target_buyer || '',
      business_goal: sme.business_goal || '',
      notes: sme.notes || '',

      raw_overall: parseMaybeJson(sme.raw_overall, {}),
      weighted_overall: parseMaybeJson(sme.weighted_overall, {}),
      category_scores: parseMaybeJson(sme.category_scores, []),
      weighted_category_breakdown: parseMaybeJson(sme.weighted_category_breakdown, []),
      scoring_summary: parseMaybeJson(sme.scoring_summary, {}),
      answered_questions: parseMaybeJson(sme.answered_questions, []),

      retrieved_documents: docs.map(d => ({
        doc_id: d.json.doc_id || '',
        doc_title: d.json.doc_title || '',
        doc_type: d.json.doc_type || '',
        source: d.json.source || '',
        category: d.json.category || '',
        industry: d.json.industry || '',
        region: d.json.region || '',
        buyer_type: d.json.buyer_type || '',
        topic_tags: d.json.topic_tags || '',
        priority: d.json.priority || '',
        summary: d.json.summary || '',
        link: d.json.link || '',
        retrieval_score: d.json.retrieval_score || 0,
        retrieval_reasons: d.json.retrieval_reasons || []
      })),

      retrieved_chunks: chunks.map(c => ({
        chunk_id: c.json.chunk_id || '',
        doc_title: c.json.doc_title || '',
        chunk_text: c.json.chunk_text || '',
        source_section_or_page: c.json.source_section_or_page || '',
        summary: c.json.summary || '',
        evidence_type: c.json.evidence_type || '',
        category: c.json.category || '',
        subcategory: c.json.subcategory || '',
        tags: c.json.tags || '',
        industry_scope: c.json.industry_scope || '',
        buyer_scope: c.json.buyer_scope || '',
        region_scope: c.json.region_scope || '',
        strength: c.json.strength || '',
        citation_label: c.json.citation_label || '',
        retrieval_score: c.json.retrieval_score || 0,
        retrieval_reasons: c.json.retrieval_reasons || []
      }))
    }
  }
];

const sme = $('Normalize Retrieval Outputs').first().json;
const matchedDocs = $('Select Matching Documents').all().map(i => i.json);
const chunks = $input.all();

// ---------- helpers ----------
function norm(value) {
  return String(value || '').toLowerCase().trim();
}

function splitList(value) {
  return String(value || '')
    .split(/[;,]/)
    .map(v => v.trim().toLowerCase())
    .filter(Boolean);
}

function fieldMatches(chunkValue, smeValue) {
  const c = norm(chunkValue);
  const s = norm(smeValue);

  if (!c || c === 'any' || c === 'all' || c === 'multi' || c === 'global') return true;
  if (!s) return false;

  const cList = splitList(c);
  const sList = splitList(s);

  return cList.some(x => sList.includes(x));
}

function tagHitCount(chunkTags, text) {
  const tags = splitList(chunkTags);
  const body = norm(text);

  if (!tags.length || !body) return 0;

  let count = 0;
  for (const tag of tags) {
    if (body.includes(tag)) count += 1;
  }
  return count;
}

function strengthScore(value) {
  const s = norm(value);
  if (s === 'high') return 3;
  if (s === 'medium') return 2;
  if (s === 'low') return 1;
  return 0;
}

// ---------- SME context ----------
const smeIndustry = norm(sme.industry);
const smeRegion = norm(sme.target_market_region);
const smeBuyer = norm(sme.target_buyer);
const smeGoal = norm(sme.business_goal);
const smeNotes = norm(sme.notes);
const smeSubindustry = norm(sme.subindustry);
const smeLocation = norm(sme.company_location);

const smeContextText = [
  sme.industry,
  sme.subindustry,
  sme.target_market_region,
  sme.target_buyer,
  sme.business_goal,
  sme.notes
].filter(Boolean).join(' ').toLowerCase();

// ---------- matched docs lookup ----------
const matchedDocTitles = new Set(
  matchedDocs.map(d => norm(d.doc_title)).filter(Boolean)
);

const matchedDocByTitle = new Map(
  matchedDocs.map(d => [norm(d.doc_title), d])
);

// ---------- score chunks ----------
const scored = chunks
  .map(item => {
    const chunk = item.json;
    const chunkDocTitle = norm(chunk.doc_title);

    // only consider chunks from already-matched documents
    if (!matchedDocTitles.has(chunkDocTitle)) return null;

    const parentDoc = matchedDocByTitle.get(chunkDocTitle) || {};

    let score = 0;
    const reasons = [];

    // inherit parent doc retrieval score
    const parentScore = Number(parentDoc.retrieval_score || 0);
    score += parentScore;
    if (parentScore > 0) reasons.push(`parent doc score: ${parentScore}`);

    // strength
    const sScore = strengthScore(chunk.strength);
    score += sScore;
    if (sScore > 0) reasons.push(`strength: ${chunk.strength}`);

    // industry
    if (fieldMatches(chunk.industry_scope, smeIndustry)) {
      score += 3;
      reasons.push(`industry_scope match: ${chunk.industry_scope}`);
    }

    // region
    if (fieldMatches(chunk.region_scope, smeRegion) || fieldMatches(chunk.region_scope, smeLocation)) {
      score += 2;
      reasons.push(`region_scope match: ${chunk.region_scope}`);
    }

    // buyer
    if (fieldMatches(chunk.buyer_scope, smeBuyer)) {
      score += 2;
      reasons.push(`buyer_scope match: ${chunk.buyer_scope}`);
    }

    // tags against SME context
    const tagHits = tagHitCount(chunk.tags, smeContextText);
    if (tagHits > 0) {
      score += tagHits * 2;
      reasons.push(`chunk tag hits: ${tagHits}`);
    }

    // summary relevance
    const summaryHits = tagHitCount(chunk.summary, `${smeGoal} ${smeNotes} ${smeSubindustry}`);
    if (summaryHits > 0) {
      score += Math.min(summaryHits, 2);
      reasons.push('chunk summary relevance');
    }

    return {
      json: {
        chunk_id: chunk.chunk_id || '',
        doc_title: chunk.doc_title || '',
        chunk_text: chunk.chunk_text || '',
        source_section_or_page: chunk.source_section_or_page || '',
        summary: chunk.summary || '',
        evidence_type: chunk.evidence_type || '',
        category: chunk.category || '',
        subcategory: chunk.subcategory || '',
        tags: chunk.tags || '',
        industry_scope: chunk.industry_scope || '',
        buyer_scope: chunk.buyer_scope || '',
        region_scope: chunk.region_scope || '',
        strength: chunk.strength || '',
        citation_label: chunk.citation_label || '',
        retrieval_score: score,
        retrieval_reasons: reasons
      }
    };
  })
  .filter(Boolean)
  .sort((a, b) => b.json.retrieval_score - a.json.retrieval_score);

// keep this small for the prompt
return scored.slice(0, 18);
